import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import Header from '../../components/ui/Header';
import Footer from '../../components/ui/Footer';
import Icon from '../../components/AppIcon';
import Button from '../../components/ui/Button';
import { useToast } from '../../contexts/ToastContext';

// Mock Data for the initial Pilot
const MOCK_PITCHES = [
    {
        id: 'PITCH-001',
        title: 'EduFund AI',
        sector: 'FinTech / Education',
        stage: 'MVP Built',
        founder: 'David O.',
        problem: 'Over 60% of brilliant students drop out of university due to delayed scholarship disbursements and lack of bridge financing.',
        vision: 'A micro-lending protocol that uses academic performance as a credit score to instantly advance tuition funds.',
        funding_ask: '$15,000 Seed',
        status: 'pending' // pending, shortlisted, passed
    },
    {
        id: 'PITCH-002',
        title: 'SolarDesk',
        sector: 'Hardware / Social Impact',
        stage: 'Early Traction',
        founder: 'Amina S.',
        problem: 'Rural students cannot study after 6 PM due to frequent grid collapses and expensive generator fuel.',
        vision: 'Affordable, recycled-plastic school desks integrated with highly efficient solar panels and LED reading lamps.',
        funding_ask: '$8,500 Seed',
        status: 'pending'
    },
    {
        id: 'PITCH-003',
        title: 'MedSync Africa',
        sector: 'Healthcare',
        stage: 'Idea Concept',
        founder: 'Dr. Chike N.',
        problem: 'Pharmacy stockouts cause 30% of preventable fatalities in local clinics because inventory data isn\'t shared centrally.',
        vision: 'A lightweight blockchain ledger connecting local pharmacies to redistribute emergency drugs within 30 minutes.',
        funding_ask: '$5,000 MVP Grant',
        status: 'pending'
    }
];

const DealRoom = () => {
    const navigate = useNavigate();
    const { addToast } = useToast();
    const [pitches, setPitches] = useState(MOCK_PITCHES);
    const [activeTab, setActiveTab] = useState('pipeline'); // pipeline, shortlisted

    const handleAction = (id, action) => {
        if (action === 'intro') {
            addToast('An introduction request has been sent to the founder.', 'success');
        } else if (action === 'shortlist') {
            setPitches(pitches.map(p => p.id === id ? { ...p, status: 'shortlisted' } : p));
            addToast('Pitch added to your private shortlist.', 'info');
        } else if (action === 'pass') {
            setPitches(pitches.map(p => p.id === id ? { ...p, status: 'passed' } : p));
            addToast('Pitch moved to passed archive.', 'error');
        }
    };

    const visiblePitches = pitches.filter(p => {
        if (activeTab === 'pipeline') return p.status === 'pending';
        if (activeTab === 'shortlisted') return p.status === 'shortlisted';
        return false;
    });

    return (
        <div className="min-h-screen bg-slate-950 flex flex-col selection:bg-amber-500/30">
            <Header />

            <main className="flex-1 pt-24 pb-20">
                {/* Hero / Header */}
                <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mb-12">
                    <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                        <div>
                            <div className="inline-flex items-center gap-2 px-3 py-1 bg-amber-500/10 border border-amber-500/20 rounded-full mb-4">
                                <Icon name="Crown" size={12} className="text-amber-500" />
                                <span className="text-[10px] font-black uppercase tracking-widest text-amber-500">Investor Access Level</span>
                            </div>
                            <h1 className="text-4xl md:text-5xl font-black text-white italic tracking-tighter">
                                Syndicate <span className="text-amber-500">Deal Room</span>
                            </h1>
                            <p className="text-slate-400 font-medium mt-2 max-w-2xl">
                                Exclusive first-look access to the top 1% of vetted founders graduating from the LUC Academy.
                            </p>
                        </div>
                        
                        <div className="flex bg-white/5 border border-white/10 rounded-xl p-1 shrink-0">
                            <button 
                                onClick={() => setActiveTab('pipeline')}
                                className={`px-6 py-3 rounded-lg text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'pipeline' ? 'bg-amber-500 text-white shadow-lg' : 'text-slate-400 hover:text-white'}`}
                            >
                                Deal Pipeline ({pitches.filter(p => p.status === 'pending').length})
                            </button>
                            <button 
                                onClick={() => setActiveTab('shortlisted')}
                                className={`px-6 py-3 rounded-lg text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'shortlisted' ? 'bg-slate-800 text-white shadow-lg' : 'text-slate-400 hover:text-white'}`}
                            >
                                Shortlisted ({pitches.filter(p => p.status === 'shortlisted').length})
                            </button>
                        </div>
                    </div>
                </div>

                {/* Pitch Feed */}
                <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 space-y-6">
                    {visiblePitches.length === 0 ? (
                        <div className="py-20 text-center bg-white/5 border border-white/10 rounded-[2.5rem]">
                            <div className="w-20 h-20 bg-slate-900 rounded-full flex items-center justify-center mx-auto mb-6">
                                <Icon name="Inbox" size={32} className="text-slate-500" />
                            </div>
                            <h3 className="text-2xl font-black text-white italic mb-2">No Active Pitches Here</h3>
                            <p className="text-slate-400 font-medium">You have reviewed all available deals in this pipeline.</p>
                        </div>
                    ) : (
                        visiblePitches.map(pitch => (
                            <div key={pitch.id} className="bg-slate-900/50 backdrop-blur-xl border border-white/10 hover:border-amber-500/30 transition-all rounded-[2.5rem] p-8 md:p-10 shadow-2xl relative overflow-hidden group">
                                <div className="absolute top-0 right-0 w-64 h-64 bg-amber-500/5 rounded-full blur-3xl -mr-32 -mt-32 opacity-0 group-hover:opacity-100 transition-opacity duration-700" />
                                
                                <div className="flex flex-col lg:flex-row gap-10 relative z-10">
                                    {/* Left Content */}
                                    <div className="flex-1 space-y-6">
                                        <div className="flex items-center gap-3">
                                            <span className="px-3 py-1 bg-white/10 text-white text-[10px] font-black uppercase tracking-widest rounded-lg">
                                                {pitch.sector}
                                            </span>
                                            <span className="px-3 py-1 bg-amber-500/20 text-amber-500 border border-amber-500/20 text-[10px] font-black uppercase tracking-widest rounded-lg">
                                                {pitch.stage}
                                            </span>
                                        </div>
                                        
                                        <div>
                                            <h2 className="text-3xl md:text-4xl font-black text-white italic tracking-tighter mb-2">
                                                {pitch.title}
                                            </h2>
                                            <p className="text-slate-500 text-sm font-bold uppercase tracking-widest">
                                                Founder: <span className="text-slate-300">{pitch.founder}</span>
                                            </p>
                                        </div>

                                        <div className="grid md:grid-cols-2 gap-6 bg-slate-950/50 rounded-2xl p-6 border border-white/5">
                                            <div className="space-y-2">
                                                <div className="flex items-center gap-2 text-rose-500">
                                                    <Icon name="Target" size={16} />
                                                    <h4 className="text-[10px] font-black uppercase tracking-widest">The Problem</h4>
                                                </div>
                                                <p className="text-slate-300 text-sm font-medium leading-relaxed">
                                                    "{pitch.problem}"
                                                </p>
                                            </div>
                                            <div className="space-y-2">
                                                <div className="flex items-center gap-2 text-emerald-500">
                                                    <Icon name="Lightbulb" size={16} />
                                                    <h4 className="text-[10px] font-black uppercase tracking-widest">The Vision</h4>
                                                </div>
                                                <p className="text-slate-300 text-sm font-medium leading-relaxed">
                                                    "{pitch.vision}"
                                                </p>
                                            </div>
                                        </div>
                                    </div>

                                    {/* Right Action Panel */}
                                    <div className="lg:w-80 shrink-0 flex flex-col justify-center space-y-6 border-t lg:border-t-0 lg:border-l border-white/10 pt-8 lg:pt-0 lg:pl-10">
                                        <div className="text-center bg-slate-950 rounded-2xl p-6 border border-white/5">
                                            <p className="text-[10px] text-slate-500 font-black uppercase tracking-widest mb-1">Current Ask</p>
                                            <p className="text-2xl font-black text-white italic">{pitch.funding_ask}</p>
                                        </div>

                                        <div className="space-y-3">
                                            <Button 
                                                fullWidth 
                                                className="bg-white text-slate-950 hover:bg-slate-200 font-black italic shadow-xl h-14 rounded-xl"
                                                iconName="Handshake"
                                                onClick={() => handleAction(pitch.id, 'intro')}
                                            >
                                                REQUEST INTRO
                                            </Button>
                                            
                                            {activeTab === 'pipeline' && (
                                                <div className="grid grid-cols-2 gap-3">
                                                    <Button 
                                                        variant="outline"
                                                        className="border-white/10 text-white hover:bg-white/10 font-black italic text-xs h-12 rounded-xl"
                                                        iconName="Star"
                                                        onClick={() => handleAction(pitch.id, 'shortlist')}
                                                    >
                                                        SHORTLIST
                                                    </Button>
                                                    <Button 
                                                        variant="outline"
                                                        className="border-rose-500/20 text-rose-500 hover:bg-rose-500/10 font-black italic text-xs h-12 rounded-xl"
                                                        iconName="X"
                                                        onClick={() => handleAction(pitch.id, 'pass')}
                                                    >
                                                        PASS
                                                    </Button>
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                </div>
                            </div>
                        ))
                    )}
                </div>
            </main>

            <Footer />
        </div>
    );
};

export default DealRoom;
